import{_ as t}from"./chunks/changes.DknGkZuo.js";import{_ as o,o as a,c as r,a2 as n}from"./chunks/framework.CS-cBh1g.js";const u=JSON.parse('{"title":"A week with Mayhem","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workflow.md","filePath":"guide/workflow.md"}'),i={name:"guide/workflow.md"};function h(s,e,c,l,d,g){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="a-week-with-mayhem" tabindex="-1">A week with Mayhem <a class="header-anchor" href="#a-week-with-mayhem" aria-label="Permalink to &quot;A week with Mayhem&quot;">​</a></h1><p>Each workspace is useful alone, but they&#39;re built to work as a loop: drive the robot, collect logs, tell an agent (or a person) what&#39;s wrong, review the change by what it does, and deploy. This page follows that loop.</p><h2 id="before-the-robot-drives" tabindex="-1">Before the robot drives <a class="header-anchor" href="#before-the-robot-drives" aria-label="Permalink to &quot;Before the robot drives&quot;">​</a></h2><ul><li><strong>Pick the robot code folder</strong> once, on any page. Changes, Robot and the Overview all read it.</li><li><strong>Turn on log collection</strong> in <strong>Robot → Log collection</strong>. Mayhem pulls new <code>.wpilog</code> files off the roboRIO whenever the laptop is on the robot network. See <a href="/Mayhem/suite/robot#log-collection">Log collection</a>.</li><li><strong>Connect</strong> with your team number in <strong>Robot → Connection</strong> to see live state machines and the robot&#39;s current state. Mayhem only reads NetworkTables; it never commands the robot.</li><li>Work through <strong>Overview → Get to match-ready</strong>. Each item has a button that takes you to the fix.</li></ul><h2 id="after-a-practice-match" tabindex="-1">After a practice match <a class="header-anchor" href="#after-a-practice-match" aria-label="Permalink to &quot;After a practice match&quot;">​</a></h2><ol><li>The log arrives in <strong><a href="/Mayhem/suite/logs">Logs</a></strong> and is checked right away: brownouts, battery sag, loop overruns, disconnects and flickering signals.</li><li><strong>Robot → On the robot now</strong> shows which commit is running, whether it was deployed with uncommitted changes, and how it differs from <code>main</code>.</li></ol><h2 id="fixing-it" tabindex="-1">Fixing it <a class="header-anchor" href="#fixing-it" aria-label="Permalink to &quot;Fixing it&quot;">​</a></h2><p>Tell your coding agent what you saw, in its chat: the match, the log, the moment, what the robot did and what it should have done. The agent works on a branch and commits. When it says the change is ready, the branch is already waiting in Mayhem: the <strong>Changes</strong> tab shows a count, and the Overview lists it with its risk and whether a sim proof was run on it.</p><p>A teammate&#39;s branch shows up the same way; Mayhem doesn&#39;t care who wrote it.</p><h2 id="reviewing-the-change" tabindex="-1">Reviewing the change <a class="header-anchor" href="#reviewing-the-change" aria-label="Permalink to &quot;Reviewing the change&quot;">​</a></h2><p><img src="'+t+'" alt="The Changes summary"></p><p>Pick the branch under <strong>To review</strong> in <strong><a href="/Mayhem/suite/changes">Changes</a></strong>. Mayhem compares it with the commit where it left <code>main</code>, by behavior: driver controls, state machines, values, hardware, autos, and any other code that changed. A red chip means a safety change, such as a CAN ID, current limit, motor direction or gear ratio. The <strong>sim proof</strong> line shows the run recorded on that exact commit, or lets you run it: both versions built, every button pressed, every auto and your team&#39;s scenarios run, any difference replayable.</p><p>If it&#39;s right, merge the branch. If it isn&#39;t, tell the agent what&#39;s wrong in the chat. After the merge the branch moves to <strong>Merged</strong>, and Mayhem shows when it is on the robot and when a log recorded on it comes back.</p><h2 id="at-competition" tabindex="-1">At competition <a class="header-anchor" href="#at-competition" aria-label="Permalink to &quot;At competition&quot;">​</a></h2><ul><li>Keep <code>main</code> as the known-good version. If the robot is running something else and it misbehaves, <strong>Robot → On the robot now → Put main back on the robot</strong> builds and deploys <code>main</code> (robot connected and disabled).</li><li>Upload logs to the team site from <strong>Robot → Log collection → Team upload</strong> so the whole team can open them.</li></ul>',15)])])}const b=o(i,[["render",h]]);export{u as __pageData,b as default};
